package com.worldgenv2.positions;

import com.worldgenv2.graph.GraphContent;
import com.worldgenv2.graph.GraphGenerator;
import com.worldgenv2.graph.GraphNode;
import com.worldgenv2.vector.Vec3d;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/**
 * Positions provider that reads and combines points generated by all graph nodes in range on a specified {@link GraphContent} layer.
 */
public final class GraphPositionsProvider implements PositionsProvider {

    private final GraphGenerator graphGenerator;
    private final String contentLayer;
    private final long seed;
    private final double maxSearchRadius;

    public GraphPositionsProvider(GraphGenerator graphGenerator, String contentLayer, long seed) {
        this(graphGenerator, contentLayer, seed, 128.0);
    }

    public GraphPositionsProvider(GraphGenerator graphGenerator, String contentLayer, long seed, double maxSearchRadius) {
        this.graphGenerator = Objects.requireNonNull(graphGenerator, "graphGenerator");
        this.contentLayer = contentLayer != null ? contentLayer : "";
        this.seed = seed;
        this.maxSearchRadius = Math.max(1.0, maxSearchRadius);
    }

    @Override
    public List<Vec3d> getPositions(double minX, double minY, double minZ, double maxX, double maxY, double maxZ) {
        Vec3d center = new Vec3d((minX + maxX) * 0.5, (minY + maxY) * 0.5, (minZ + maxZ) * 0.5);
        double halfDiag = Math.sqrt(
            Math.pow((maxX - minX) * 0.5, 2) +
            Math.pow((maxY - minY) * 0.5, 2) +
            Math.pow((maxZ - minZ) * 0.5, 2)
        );

        List<GraphNode> nearby = graphGenerator.getNodesNear(seed, center, halfDiag + maxSearchRadius);
        List<Vec3d> result = new ArrayList<>();

        for (GraphNode node : nearby) {
            Optional<GraphContent.PositionsEntry> opt = node.getContent().getFirstPositions(contentLayer);
            if (opt.isPresent()) {
                GraphContent.PositionsEntry entry = opt.get();
                double range = entry.range();
                if (range > 0.0) {
                    List<Vec3d> rawPoints = entry.positions().getPositions(minX, minY, minZ, maxX, maxY, maxZ);
                    for (Vec3d pt : rawPoints) {
                        if (pt.distance(node.getPosition()) <= range) {
                            if (pt.x() >= minX && pt.x() <= maxX &&
                                pt.y() >= minY && pt.y() <= maxY &&
                                pt.z() >= minZ && pt.z() <= maxZ) {
                                result.add(pt);
                            }
                        }
                    }
                }
            }
        }
        return result;
    }

    public GraphGenerator getGraphGenerator() {
        return graphGenerator;
    }

    public String getContentLayer() {
        return contentLayer;
    }

    public long getSeed() {
        return seed;
    }

    public double getMaxSearchRadius() {
        return maxSearchRadius;
    }
}
